#!/usr/bin/env python3
"""Executable stranger starter/bootstrap admission court."""
import argparse, glob, json, re, sys
from pathlib import Path
RULES=json.loads(r'''{"anonymous-clone":{"key":"anonymous_clone","good":true,"standing":"REFUSED[AUTHENTICATED_CLONE_REQUIRED]"},"shallow-clone":{"key":"shallow_clone_supported","good":true,"standing":"REFUSED[SHALLOW_CLONE_UNSUPPORTED]"},"git-capability":{"key":"git_available","good":true,"standing":"UNSUPPORTED[GIT_MISSING]"},"submodule-init":{"key":"submodules_ready","good":true,"standing":"REFUSED[SUBMODULES_UNINITIALIZED]"},"clean-start":{"key":"initial_tree_clean","good":true,"standing":"REFUSED[DIRTY_INITIAL_TREE]"},"target-path-relative":{"key":"target_path_relative","good":true,"standing":"REFUSED[ABSOLUTE_TARGET_PATH]"},"target-path-no-traversal":{"key":"target_path_safe","good":true,"standing":"REFUSED[TARGET_PATH_TRAVERSAL]"},"starter-archive-present":{"key":"starter_archive_present","good":true,"standing":"REFUSED[STARTER_ARCHIVE_MISSING]"},"starter-digest":{"key":"starter_digest_valid","good":true,"standing":"REFUSED[STARTER_DIGEST_MISMATCH]"},"starter-manifest":{"key":"starter_manifest_valid","good":true,"standing":"REFUSED[STARTER_MANIFEST_INVALID]"},"safe-extraction":{"key":"safe_extraction","good":true,"standing":"REFUSED[UNSAFE_ARCHIVE_ENTRY]"},"existing-repo-detection":{"key":"existing_repo_detected","good":true,"standing":"REFUSED[EXISTING_REPO_UNDETECTED]"},"ownership-collision":{"key":"ownership_collision_free","good":true,"standing":"REFUSED[OWNERSHIP_COLLISION]"},"gitignore-preserved":{"key":"gitignore_preserved","good":true,"standing":"REFUSED[GITIGNORE_OVERWRITE]"},"file-permissions":{"key":"permissions_preserved","good":true,"standing":"REFUSED[EXECUTABLE_BIT_DRIFT]"},"starter-config":{"key":"starter_config_valid","good":true,"standing":"REFUSED[STARTER_CONFIG_INVALID]"},"ggen-pin":{"key":"ggen_exact_pin","good":true,"standing":"REFUSED[MUTABLE_GGEN_IDENTITY]"},"marketplace-pin":{"key":"marketplace_exact_pin","good":true,"standing":"REFUSED[MUTABLE_MARKETPLACE_IDENTITY]"},"pack-path":{"key":"pack_path_valid","good":true,"standing":"REFUSED[PACK_PATH_INVALID]"},"capsule-pin":{"key":"capsule_exact_pin","good":true,"standing":"REFUSED[MUTABLE_CAPSULE_IDENTITY]"},"os-support":{"key":"os_supported","good":true,"standing":"UNSUPPORTED[OPERATING_SYSTEM]"},"architecture-support":{"key":"architecture_supported","good":true,"standing":"UNSUPPORTED[ARCHITECTURE]"},"local-no-install":{"key":"local_no_install_ready","good":true,"standing":"REFUSED[LOCAL_RUNTIME_MISSING]"},"dockerless-path":{"key":"dockerless_path_ready","good":true,"standing":"UNSUPPORTED[DOCKERLESS_PATH]"},"hosted-runner":{"key":"hosted_runner_ready","good":true,"standing":"BLOCKED[HOSTED_RUNNER_PREEXEC]"},"self-hosted-runner":{"key":"self_hosted_runner_safe","good":true,"standing":"REFUSED[SELF_HOSTED_RUNNER_UNSAFE]"},"cache-identity":{"key":"cache_identity_match","good":true,"standing":"REFUSED[CACHE_IDENTITY_MISMATCH]"},"cache-reuse":{"key":"cache_reuse_safe","good":true,"standing":"REFUSED[CACHE_REUSE_UNSAFE]"},"dry-run":{"key":"dry_run_exit_zero","good":true,"standing":"BUILD_BROKEN[DRY_RUN_NONZERO]"},"dry-run-no-write":{"key":"dry_run_no_write","good":true,"standing":"BUILD_BROKEN[DRY_RUN_WROTE]"},"diff-only":{"key":"diff_only_ready","good":true,"standing":"REFUSED[DIFF_ONLY_UNAVAILABLE]"},"full-sync":{"key":"full_sync_exit_zero","good":true,"standing":"BUILD_BROKEN[SYNC_NONZERO]"},"receipt":{"key":"receipt_valid","good":true,"standing":"REFUSED[RECEIPT_INVALID]"},"replay":{"key":"replay_identical","good":true,"standing":"REFUSED[REPLAY_DRIFT]"},"second-generation":{"key":"second_generation_identical","good":true,"standing":"REFUSED[SECOND_GENERATION_DRIFT]"},"generated-pr":{"key":"generated_pr_routable","good":true,"standing":"REFUSED[GENERATED_PR_UNROUTABLE]"},"fork-permissions":{"key":"fork_permissions_sufficient","good":true,"standing":"REFUSED[FORK_PERMISSION_CEILING]"},"token-scope":{"key":"token_scope_minimal","good":true,"standing":"REFUSED[TOKEN_SCOPE_EXCESS]"},"rate-limit":{"key":"rate_limit_exposed","good":true,"standing":"BLOCKED[RATE_LIMIT_HIDDEN]"},"partial-transport":{"key":"transport_complete","good":true,"standing":"BLOCKED[PARTIAL_TRANSPORT]"},"malformed-input":{"key":"input_valid","good":true,"standing":"REFUSED[MALFORMED_INPUT]"},"capability-routing":{"key":"unsupported_typed","good":true,"standing":"REFUSED[UNTYPED_UNSUPPORTED_CAPABILITY]"},"upgrade-canary":{"key":"upgrade_canary_passed","good":true,"standing":"REFUSED[UPGRADE_CANARY_FAILED]"},"dual-run":{"key":"dual_run_consistent","good":true,"standing":"REFUSED[DUAL_RUN_DIVERGENCE]"},"rollback":{"key":"rollback_identity_bound","good":true,"standing":"REFUSED[ROLLBACK_IDENTITY_MISSING]"},"security-intake":{"key":"security_route_present","good":true,"standing":"REFUSED[SECURITY_ROUTE_MISSING]"},"support-intake":{"key":"support_route_present","good":true,"standing":"REFUSED[SUPPORT_ROUTE_MISSING]"},"sbom":{"key":"sbom_subject_match","good":true,"standing":"REFUSED[SBOM_SUBJECT_MISMATCH]"},"attestation":{"key":"attestation_subject_match","good":true,"standing":"REFUSED[ATTESTATION_SUBJECT_MISMATCH]"},"final-clean-tree":{"key":"final_tree_clean","good":true,"standing":"REFUSED[UNEXPECTED_WORKTREE_CHANGE]"}}''')
CANONICAL=json.loads(r'''{"anonymous_clone":true,"shallow_clone_supported":true,"git_available":true,"submodules_ready":true,"initial_tree_clean":true,"target_path_relative":true,"target_path_safe":true,"starter_archive_present":true,"starter_digest_valid":true,"starter_manifest_valid":true,"safe_extraction":true,"existing_repo_detected":true,"ownership_collision_free":true,"gitignore_preserved":true,"permissions_preserved":true,"starter_config_valid":true,"ggen_exact_pin":true,"marketplace_exact_pin":true,"pack_path_valid":true,"capsule_exact_pin":true,"os_supported":true,"architecture_supported":true,"local_no_install_ready":true,"dockerless_path_ready":true,"hosted_runner_ready":true,"self_hosted_runner_safe":true,"cache_identity_match":true,"cache_reuse_safe":true,"dry_run_exit_zero":true,"dry_run_no_write":true,"diff_only_ready":true,"full_sync_exit_zero":true,"receipt_valid":true,"replay_identical":true,"second_generation_identical":true,"generated_pr_routable":true,"fork_permissions_sufficient":true,"token_scope_minimal":true,"rate_limit_exposed":true,"transport_complete":true,"input_valid":true,"unsupported_typed":true,"upgrade_canary_passed":true,"dual_run_consistent":true,"rollback_identity_bound":true,"security_route_present":true,"support_route_present":true,"sbom_subject_match":true,"attestation_subject_match":true,"final_tree_clean":true}''')
FP16=re.compile(r"^[0-9a-f]{16}$")
def validate(observation):
    for edge, rule in RULES.items():
        if observation.get(rule["key"]) is not rule["good"]:
            return rule["standing"]
    return "ALIVE"
def main():
    ap=argparse.ArgumentParser()
    ap.add_argument("--fixtures",default="tests/fixtures/starter-journey/*.json")
    ap.add_argument("--min-cases",type=int,default=1)
    args=ap.parse_args(); paths=sorted(glob.glob(args.fixtures))
    if len(paths)<args.min_cases:
        print(f"REFUSED[CASE_CENSUS_UNDERFILLED]: {len(paths)} < {args.min_cases}",file=sys.stderr);return 1
    ids=set();edges_seen=set();fps=set()
    for path in paths:
        case=json.loads(Path(path).read_text()); cid=case["id"];edge=case["edge"];fp=case["semantic_fingerprint"]
        if cid in ids or edge in edges_seen or fp in fps:
            print(f"REFUSED[DUPLICATE_CASE_IDENTITY]: {path}",file=sys.stderr);return 1
        ids.add(cid);edges_seen.add(edge);fps.add(fp)
        if edge not in RULES or not FP16.fullmatch(fp):
            print(f"REFUSED[MALFORMED_CASE_IDENTITY]: {path}",file=sys.stderr);return 1
        invalid=dict(CANONICAL);invalid.update(case["invalid"])
        control=dict(CANONICAL);control.update(case.get("control",{}))
        observed=validate(invalid);control_observed=validate(control)
        if observed!=case["expected"] or control_observed!="ALIVE":
            print(f"BUILD_BROKEN[{cid}]: invalid={observed} expected={case['expected']} control={control_observed}",file=sys.stderr);return 1
    print(f"STARTER_JOURNEY: ALIVE ({len(paths)} executable negative/control pairs)")
    return 0
if __name__=="__main__":sys.exit(main())
